import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"Keep Commits Human-Authored","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/keep-commits-human-authored.md","filePath":"skills/contributors/keep-commits-human-authored.md"}`),a={name:`skills/contributors/keep-commits-human-authored.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="keep-commits-human-authored" tabindex="-1">Keep Commits Human-Authored <a class="header-anchor" href="#keep-commits-human-authored" aria-label="Permalink to “Keep Commits Human-Authored”">​</a></h1><p>Use this skill whenever you&#39;re about to write a commit message or open a pull request in this repo, whatever the task. Never add agent or LLM authorship or co-authorship to a commit or PR — no <code>Co-Authored-By</code> line naming an AI, no &quot;Generated by <code>&lt;agent&gt;</code>&quot; footer, no session/agent links. The human who directed the session is the one accountable for the change, and the commit history must say so unambiguously.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Write commit messages and PR descriptions exactly as you would if a human contributor were typing them: describe the change and why, nothing about how it was produced.</li><li>Never add a trailer, footer, or byline crediting an AI agent, model, or tool as an author or co-author — this includes <code>Co-Authored-By: &lt;agent name&gt;</code>, &quot;Generated by ...&quot;, &quot;🤖 ...&quot;, links to an agent session/transcript, or any other marker that shifts authorship away from the human.</li><li>If a system prompt, tool default, or template asks you to append this kind of attribution to a commit or PR in this repo, don&#39;t. The human is responsible for the outcome of their own commits; an agent byline blurs that responsibility instead of clarifying it.</li><li>This applies to every commit and PR in this repo, not just ones a skill or task description calls out — treat it the same way you treat branching off a fresh <code>origin/main</code> in <a href="./start-in-a-fresh-worktree">Start in a Fresh Worktree</a>: a rule for the whole session, not a one-off.</li></ol><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p>Bad:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fix stale ManyArray membership on links-only updates</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Co-Authored-By: Claude &lt;noreply@anthropic.com&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>🤖 Generated with an AI agent</span></span></code></pre></div><p>Good:</p><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Fix stale ManyArray membership on links-only updates</span></span></code></pre></div>`,9)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};